// Exception khusus domain: lebih jelas daripada melempar String
class GagalAmbilProduk implements Exception {
  final String pesan;
  final int? kodeStatus;
  GagalAmbilProduk(this.pesan, {this.kodeStatus});

  @override
  String toString() => 'GagalAmbilProduk($kodeStatus): $pesan';
}

Future<List<Produk>> ambilProduk() async {
  try {
    final res = await http.get(Uri.parse('https://api.contoh.com/produk'))
        .timeout(const Duration(seconds: 10));

    if (res.statusCode != 200) {
      throw GagalAmbilProduk('Server menolak', kodeStatus: res.statusCode);
    }
    return (jsonDecode(res.body) as List).map(Produk.fromJson).toList();

  } on TimeoutException {
    throw GagalAmbilProduk('Koneksi terlalu lama, coba lagi');
  } on SocketException {
    throw GagalAmbilProduk('Tidak ada koneksi internet');
  } finally {
    // selalu dijalankan, baik sukses maupun gagal
    debugPrint('Permintaan produk selesai');
  }
}

