// Android — ML Kit Text Recognition (OCR struk), 100% on-device
val recognizer = TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS)

fun scanStruk(bitmap: Bitmap, onHasil: (String) -> Unit) {
    val image = InputImage.fromBitmap(bitmap, 0)
    recognizer.process(image)
        .addOnSuccessListener { hasil -> onHasil(hasil.text) }   // teks mentah struk
        .addOnFailureListener { e -> onGagal(e) }                // wajib ditangani (Bab 4)
}

// iOS — Vision framework (padanan on-device)
func scanStruk(_ image: CGImage) {
    let request = VNRecognizeTextRequest { req, _ in
        let teks = (req.results as? [VNRecognizedTextObservation])?
            .compactMap { $0.topCandidates(1).first?.string }.joined(separator: "\n")
        self.onHasil(teks ?? "")
    }
    request.recognitionLevel = .accurate
    try? VNImageRequestHandler(cgImage: image).perform([request])
}

